1: var http = require("http");
2: var fs = require('fs');
3: 
4: // don't let users crawl up the folder structure by using a/../../../c/d
5: var cleanUrl = function(url) { 
6: 	while(url.indexOf('..').length > 0) { url = url.replace('..', ''); }
7: 	return url;
8: };
9: 
10: /*  
11: example usage:
12: 	require('http').createServer(function (req, res) {
13: 		server.handleRequest(port, path, req, res, vpath);
14: 	}).listen(port);
15: */
16: exports.handleRequest = function(vpath, path, req, res, readOnly, logHeadRequests) {	
17: 	// vpath: (optional) virtual path to host in the url
18: 	// path: the file system path to serve
19: 	// readOnly: whether to allow modifications to the file
20: 
21: 	// our error handler
22: 	var writeError = function (err, code) { 
23: 		code = code || 500;
24: 		console.log('Error ' + code + ': ' + err);
25: 		// write the error to the response, if possible
26: 		try {			
27: 			res.statusCode = code;
28: 			res.setHeader('Content-Type', 'application/json');
29: 			res.end(JSON.stringify(err));	
30: 		} catch(resErr) {
31: 			console.log('failed to write error to response: ' + resErr);
32: 		}
33: 	};
34: 
35: 	if(path.lastIndexOf('/') !== path.length - 1) { path += '/'; } // make sure path ends with a slash	
36: 	var parsedUrl = require('url').parse(req.url);	
37: 	var query = query ? {} : require('querystring').parse(parsedUrl.query);
38:     var url = cleanUrl(parsedUrl.pathname);
39: 	
40: 	// normalize the url such that there is no trailing or leading slash /
41: 	if(url.lastIndexOf('/') === url.length - 1) { url = url.slice(0, url.length ); }
42: 	if(url[0] === '/') { url = url.slice(1, url.length);  }
43: 
44: 	// check that url begins with vpath
45: 	if(vpath && url.indexOf(vpath) != 0) {
46: 		console.log('url does not begin with vpath');
47: 		throw 'url [' + url + '] does not begin with vpath [' + vpath + ']';
48: 	}
49: 	
50: 	if(req.method != 'HEAD') {
51: 		console.log(req.method + ' ' + req.url);
52: 	}
53: 	var relativePath = vpath ?
54: 		path + url.slice(vpath.length + 1, url.length):
55: 		path + url;	
56: 	
57: 	try {
58: 		if(readOnly && req.method != 'GET') {
59: 			writeError(req.method + ' forbidden on this resource', 403);
60: 		} else {
61: 			switch(req.method) {
62: 				case 'HEAD':
63: 					if(logHeadRequests) {
64: 						console.log('head: ' + relativePath);				
65: 					}
66: 					fs.stat(relativePath, function(err, stats) { // determine if the resource is a file or directory
67: 						if(err) { writeError(err); } 
68: 						else {						
69: 							res.setHeader('Last-Modified', stats.mtime);		
70: 							if(stats.isDirectory()) {								
71: 								res.setHeader('Content-Type', query.dir == 'json' ? 'application/json' : 'text/html');
72: 							} else {
73: 								var type = require('mime').lookup(relativePath);
74: 								res.setHeader('Content-Type', type);
75: 							}
76: 							res.end();							
77: 						}
78: 					});
79: 					break;
80: 				case 'GET': // returns file or directory contents
81: 					console.log('relativePath: ' + relativePath);
82: 					if(url === 'favicon.ico') { 	
83: 						res.end(); // if the browser requests favicon, just return an empty response
84: 					} else {
85: 						fs.stat(relativePath, function(err, stats) { // determine if the resource is a file or directory
86: 							if(err) { writeError(err); } 
87: 							else {
88: 								if(stats.isDirectory()) {
89: 									res.setHeader('Last-Modified', stats.mtime);							
90: 									// if it's a directory, return the files as a JSONified array
91: 									console.log('reading directory ' + relativePath);
92: 									fs.readdir(relativePath, function(err, files) {
93: 										if(err) { 
94: 											console.log('writeError');
95: 											writeError(err); 
96: 										}
97: 										else {
98: 											var results = [];
99: 											var search = {};
100: 											search.stats = function(files) {
101: 												if(files.length) { 
102: 													var file = files.shift();
103: 													fs.stat(relativePath + '/' + file, function(err, stats) { 
104: 														if(err) { writeError(err); } 
105: 														else {
106: 															stats.name = file;
107: 															stats.isFile = stats.isFile();
108: 															stats.isDirectory = stats.isDirectory();
109: 															stats.isBlockDevice = stats.isBlockDevice();
110: 															stats.isFIFO = stats.isFIFO();
111: 															stats.isSocket = stats.isSocket();
112: 															results.push(stats);
113: 															search.stats(files);															
114: 														}
115: 													});
116: 												} else {
117: 													if(query.dir == 'json') {
118: 														res.setHeader('Content-Type', 'application/json');
119: 														res.write(JSON.stringify(results)); 
120: 														res.end();
121: 													} else { 
122: 														res.setHeader('Content-Type', 'text/html');											
123: 														res.write('<html><body>');
124: 														for(var f = 0; f < results.length; f++) {
125: 															var name = results[f].name;
126: 															var normalized = url + '/' + name;
127: 															while(normalized[0] == '/') { normalized = normalized.slice(1, normalized.length); }
128: 															res.write('\r\n<p><a href="/' + normalized + '">' + name + '</a></p>');
129: 														}
130: 														res.end('\r\n</body></html>');
131: 													}
132: 												}
133: 											};
134: 											search.stats(files);
135: 										}
136: 									});
137: 								} else {
138: 									// if it's a file, return the contents of a file with the correct content type
139: 									console.log('reading file ' + relativePath);
140: 									var type = require('mime').lookup(relativePath);
141: 									res.setHeader('Content-Type', type);
142: 									fs.readFile(relativePath, function(err, data) { 
143: 										if(err) { writeError(err); }
144: 										else {
145: 											res.end(data); 
146: 										}
147: 									});
148: 								}
149: 							}
150: 						});
151: 					}
152: 					return;
153: 				case 'PUT': // write a file
154: 					console.log('writing ' + relativePath);
155: 					var stream = fs.createWriteStream(relativePath);		
156: 					stream.ok = true;
157: 					req.pipe(stream); // TODO: limit data length
158: 					req.on('end', function() {				
159: 						if(stream.ok) {
160: 							res.end();					
161: 						}
162: 					});
163: 					stream.on('error', function(err) { 										
164: 						stream.ok = false;
165: 						writeError(err);
166: 					});
167: 					return;
168: 				case 'POST': // create a directory or rename a file or directory
169: 					if(query.rename) { // rename a file or directory
170: 						console.log('rename: ' + relativePath);
171: 						// e.g., http://localhost/old-name.html?rename=new-name.html
172: 						query.rename = cleanUrl(query.rename);
173: 						if(vpath) { 
174: 							if(query.rename.indexOf('/' + vpath + '/') == 0) { 
175: 								query.rename = query.rename.slice(vpath.length + 2, query.rename.length);
176: 							} else {
177: 								throw 'renamed url [' + query.rename + '] does not begin with vpath [' + vpath + ']';
178: 							}
179: 						} 
180: 						console.log('renaming ' + relativePath + ' to ' + path + query.rename);
181: 						fs.rename(relativePath, path + query.rename, function(err) {
182: 							if(err) { writeError(err); } 
183: 							else {
184: 								res.end();
185: 							}
186: 						});
187: 					} else if(query.create == 'directory') { // rename a directory
188: 						// e.g., http://localhost/new-directory?create=directory
189: 						console.log('creating directory ' + relativePath);
190: 						fs.mkdir(relativePath, 0777, function(err) { 
191: 							if(err) { writeError(err); } 
192: 							else {
193: 								res.end();
194: 							}
195: 						});
196: 					} else {
197: 						console.log('relativePath: ' + relativePath);
198: 						writeError('valid queries are ' + url + '?rename=[new name] or ' + url + '?create=directory');
199: 					}
200: 					return;
201: 				case 'DELETE': // delete a file or directory				
202: 					fs.stat(relativePath, function(err, stats) { 
203: 						if(err) { writeError(err); } 
204: 						else {
205: 							if(stats.isDirectory()) { // delete a directory
206: 								console.log('deleting directory ' + relativePath);
207: 								fs.rmdir(relativePath, function(err) {
208: 									if(err) { writeError(err); }
209: 									else { res.end(); }
210: 								});
211: 							} else { // delete a file
212: 								console.log('deleting file ' + relativePath);
213: 								fs.unlink(relativePath, function(err) {
214: 									if(err) { writeError(err); }
215: 									else { res.end(); }
216: 								});
217: 							}
218: 						}
219: 					});			
220: 					return;
221: 				default: // unsupported method! tell the client ...
222: 					console.log('unsupported: ' + relativePath);				
223: 					writeError('Method ' + method + ' not allowed', 405);
224: 					return;
225: 			}
226: 		}
227: 	} catch(err) { 
228: 		// file system ('fs') errors are just bubbled up to this error handler
229: 		// for example, if the GET is called on a non-existent file, an error will be thrown
230: 		// and caught here
231: 		// writeError will write the error information to the response
232: 		writeError('unhandled error: ' + err);
233: 	}
234: };

